  "accLinkFailed": "Bu bağlantının süresi dolmuş veya daha önce kullanılmış olabilir. Giriş yapmak veya yeni e-posta istemek için Hesap’ı açın.",
  "privFooter": "Gizlilik ve depolama",
  "privTitle": "Gizlilik ve tarayıcı depolaması",
  "privClose": "Gizlilik bildirimini kapat",
  "privWho": "Kim sorumlu?",
  "privWhat": "Neyi neden kullanıyoruz",
  "privStorage": "Tarayıcı depolaması",
  "privOther": "Diğer mevcut özellikler",
  "privProviders": "Hizmet sağlayıcılar ve uluslararası aktarımlar",
  "privRetention": "Saklama ve silme",
  "privRights": "Haklarınız",
  "noticeReopen": "Depolama bildirimi",
  "noticeLabel": "Tarayıcı depolama bildirimi",
  "noticeText": "Cook, kullandığınız yemek pişirme ve giriş özellikleri için tarayıcı depolamasını kullanır. Reklam veya analiz amaçlı depolama eklenmez.",
  "noticeClose": "Depolama bildirimini kapat",
  "privDraftLabel": "Taslak — 28 Ekim 2026’da güncellendi.",
  "privDraft": "Hesap özellikleri şu anda test ediliyor. Aşağıdaki işletmeci ve hizmet bilgilerinin herkese açık yayından önce tamamlanması gerekir.",
  "privWho1": "Cook’un işletmecisi: [işletmecinin yasal adı ve posta adresi]. Gizlilikle ilgili soru ve talepler için [gizlilik e-posta adresi] adresine yazın. Bu bilgilerin kayıtlar açılmadan önce tamamlanması gerekir.",
  "privWhat1": "Hesap oluşturduğunuzda hesabınızı sunmak ve korumak için e-posta adresinizi, bir hesap kimliğini, şifreyle kimlik doğrulama kayıtlarını ve doğrulama durumunu kullanırız. Şifreler kimlik doğrulama sağlayıcısı tarafından güvenli özetler olarak işlenir; Cook okunabilir şifre saklamaz. Ayarlarınızı tüm cihazlarda geri yüklemek için mutfak düzeninizi, seçtiğiniz dili, temayı ve ölçü birimlerini saklarız. Hesap için e-posta ve şifre gereklidir; tarifleri hesap olmadan da görüntüleyebilirsiniz.",
  "privWhat2": "Hesap ve ayarların işlenmesi, talep ettiğiniz hesap hizmetini sunmak için gereklidir (GDPR madde 6(1)(b)). Sınırlı güvenlik ve kötüye kullanımı önleme kayıtları, gerekli olduğu ölçüde ve dengeleme yapılarak meşru menfaat temelinde (madde 6(1)(f)) işlenebilir. Doğrulama ve şifre sıfırlama e-postaları pazarlama değil, hizmet mesajlarıdır. Hesap özelliği reklam veya analiz eklemez.",
  "privStorage1": "Cook, mutfağınızı, pişirme ilerlemenizi ve seçimlerinizi aynı sekmedeki sayfalar arasında taşımak için sessionStorage kullanır. Giriş yaptığınızda oturum açma oturumunuzu da tutar. Tarayıcı bunu genellikle sekme oturumu bittiğinde temizler, ancak tarayıcının oturum geri yükleme özelliği bunu koruyabilir. Çıkış yapmak Cook’un sekme verilerini temizler. Depolama bildiriminin kapatılması yalnızca o sekmede hatırlanır. Cook’un kendi betikleri çerez yerleştirmez. Barındırma veya hizmet sağlayıcılarınızın, yayından önce belgelenmesi gereken kendi güvenlik işlemleri olabilir.",
  "privStorage2": "Tamam ve depolama bildirimindeki kapatma düğmesi yalnızca bildirimi kapatır. Analiz, reklam veya başka isteğe bağlı izlemeye izin vermez. Gelecekte zorunlu olmayan her depolama, başlamadan önce ayrı bir seçim gerektirecek; reddetmek ve geri çekmek de aynı kolaylıkta olacaktır.",
  "privOther1": "Tarif listesinin mevcut ses özelliği, konuşma dilini seçmek için IP adresinizi kullanarak country.is’ten yaklaşık bir ülke ister. Mikrofonla tanımayı kullanırsanız tarayıcınız sesi kendi konuşma tanıma sağlayıcısına gönderebilir. Malzemeleri yazarak da girebilirsiniz. Bu sağlayıcılar, politikaları ve bu özelliklerin hukuki dayanağı herkese açık yayından önce incelenmelidir.",
  "privProviders1": "Planlanan hesap sağlayıcısı: Supabase (yönetilen PostgreSQL ve kimlik doğrulama), seçilmiş bir AB veritabanı bölgesiyle. E-posta sağlayıcısı: [sağlayıcı]. Web sitesi barındırma: [sağlayıcı]. İşletmeci; gerçek sağlayıcıları, veri işleme sözleşmelerini, alt işleyenleri, kayıtların konumlarını ve AEA dışına yapılan aktarımları doğrulamalıdır. AB’deki bir veritabanı bölgesi tek başına uluslararası aktarımları dışlamaz. Gerektiğinde geçerli yeterlilik kararını veya sözleşmesel güvenceleri ve bunların bir kopyasının nasıl alınacağını belirtin.",
  "privRetention1": "Hesap ayarları hesabınız etkin olduğu sürece saklanır. Silme talebini yukarıdaki gizlilik iletişim adresi üzerinden iletebilirsiniz. Yayından önce işletmeci; silme taleplerine yanıt sürecini, doğrulanmamış hesapların sona erme süresini ve güvenlik kayıtları ile yedeklerin saklama sürelerini belirlemelidir. Silinen veriler, belgelenen yedek saklama süresi bitene kadar erişimi kısıtlı yedeklerde kalabilir.",
  "privRights1": "Geçerli koşullara bağlı olarak erişim, düzeltme, silme, kısıtlama veya taşınabilirlik talep edebilir ya da meşru menfaate dayalı işlemeye itiraz edebilirsiniz. Yukarıdaki işletmeciyle iletişime geçin; talepler genellikle bir ay içinde yanıtlanır ve yasal uzatmalar açıklanır. Macaristan’daki NAIH (naih.hu) dahil olmak üzere denetim makamınıza şikâyette bulunabilirsiniz. Cook, hesap ayarlarını hukuki ya da benzer şekilde önemli sonuçlar doğuran otomatik kararlar için kullanmaz.",
