  "Even thickness": "Eşit kalınlık",
  "Season the chicken": "Tavuğu baharatlayın",
  "Rub it well in a bowl with salt, a little black pepper and some oil.": "Bir kâsede tuz, biraz karabiber ve biraz yağla iyice ovun.",
  "Evenly coated": "Eşit şekilde kaplandı",
  "Heat a little oil in the pan on medium-high and add the chicken.": "Tavada biraz yağı orta-yüksek ateşte ısıtın ve tavuğu ekleyin.",
  "Sizzling": "Cızırdıyor",
  "Fry side #": "# . yüzü kızartın",
  "Fry the first side.": "İlk yüzü kızartın.",
  "Golden underneath": "Altı altın renginde",
  "Flip": "Çevirin",
  "Turn the chicken over.": "Tavuğu ters çevirin.",
  "Flipped": "Çevrildi",
  "Fry the second side.": "İkinci yüzü kızartın.",
  "Check doneness": "Pişip pişmediğini kontrol edin",
  "Cut the thickest piece in half: it must be white all the way through.": "En kalın parçayı ikiye kesin: baştan sona beyaz olmalı.",
  "White throughout": "Her yeri beyaz",
  "Let it rest": "Dinlendirin",
  "Take it out and let it rest.": "Çıkarın ve dinlendirin.",
  "Dice it into 1 to 2 cm cubes.": "1 ila 2 cm'lik küpler hâlinde doğrayın.",
  "Cubes": "Küpler",
  "Grate the parmesan": "Parmesan'ı rendeleyin",
  "Grate the parmesan (skip if already grated).": "Parmesan'ı rendeleyin (zaten rendelenmişse atlayın).",
  "Add the lettuce. Scatter the chicken cubes, the parmesan and the croutons on it. Sprinkle a little Worcestershire sauce and add some mayonnaise on top.": "Marulu ekleyin. Üzerine tavuk küplerini, Parmesan'ı ve krutonları dağıtın. Biraz Worcestershire sosu serpin ve üzerine biraz mayonez koyun.",
  "Make the mayonnaise · Grate the parmesan": "Mayonezi yapın · Parmesan'ı rendeleyin",
