  "Let it rest · Dice the chicken": "Dinlendirin · Tavuğu küp doğrayın",
  "Preheat the oven": "Fırını ısıtın",
  "Turn the oven on to 190 °C conventional (170 °C fan), middle rack.": "Fırını alt-üst ısıtmada 190 °C'ye (fanlı 170 °C) açın, orta raf.",
