  "Squeeze out all the liquid.": "Bütün suyunu sıkın.",
  "No more liquid": "Su kalmadı",
  "Mix it": "Karıştırın",
  "In a bowl: the cucumber, the Greek yogurt, the garlic, the dill, some lemon juice (or vinegar), a pinch of salt if needed, the olive oil and black pepper. Stir well.": "Bir kâsede: salatalık, süzme yoğurt, sarımsak, dereotu, biraz limon suyu (veya sirke), gerekirse bir tutam tuz, zeytinyağı ve karabiber. İyice karıştırın.",
