  "1 hour passed": "1 saat geçti",
  "Let it drain · Squeeze the cucumber": "Süzülsün · Salatalığı sıkın",
  "Get the jars ready": "Kavanozları hazırlayın",
  "Set out small-ish jars, one per serving.": "Porsiyon başına bir tane olmak üzere küçükçe kavanozlar çıkarın.",
  "Jars ready": "Kavanozlar hazır",
  "Oats and chia": "Yulaf ve chia",
  "Add the rolled oats, then the chia seeds to each jar.": "Her kavanoza önce yulaf ezmesini, sonra chia tohumunu ekleyin.",
  "Dry layer in each jar": "Her kavanozda kuru katman",
  "Milk, yogurt, sweetener": "Süt, yoğurt, tatlandırıcı",
